431	        text.append("Hóspede: ").append(guestName).append(" (CPF ").append(guestCpf).append(")\n");
432	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
433	        text.append("Entrada: ").append(TextFormat.date(checkIn))
