343	/** Every message the inn sent, so the front desk can check what each guest received. */
344	public final class SentMessages {
345	
346	    private final DataSource dataSource;
347	
348	    public SentMessages(DataSource dataSource) {
349	        this.dataSource = dataSource;
350	    }
351	
352	    Message add(String channel, String to, String subject, String body) {
353	        try (Connection connection = dataSource.getConnection();
354	                PreparedStatement insert = connection.prepareStatement(
355	                        "INSERT INTO messages (channel, recipient, subject, body) VALUES (?, ?, ?, ?) RETURNING id")) {
356	            insert.setString(1, channel);
357	            insert.setString(2, to);
358	            insert.setString(3, subject);
359	            insert.setString(4, body);
360	            try (ResultSet generated = insert.executeQuery()) {
361	                generated.next();
362	                return new Message(generated.getLong("id"), channel, to, subject, body);
363	            }
364	        } catch (SQLException failure) {
365	            throw new IllegalStateException("could not keep the message to " + to, failure);
366	        }
367	    }
368	
369	    public List<Message> all() {
370	        try (Connection connection = dataSource.getConnection();
371	                PreparedStatement select = connection.prepareStatement(
372	                        "SELECT id, channel, recipient, subject, body FROM messages ORDER BY id");
373	                ResultSet rows = select.executeQuery()) {
374	            List<Message> messages = new ArrayList<>();
375	            while (rows.next()) {
376	                messages.add(new Message(
377	                        rows.getLong("id"),
378	                        rows.getString("channel"),
379	                        rows.getString("recipient"),
380	                        rows.getString("subject"),
381	                        rows.getString("body")));
382	            }
383	            return messages;
384	        } catch (SQLException failure) {
385	            throw new IllegalStateException("could not read the sent messages", failure);
386	        }
387	    }
