397	/** The receipt the guest gets when the reservation is confirmed, at check-out, and on request. */
398	public record ReservationReceipt(
399	        String title,
400	        long reservationId,
401	        String guestName,
402	        String guestCpf,
403	        int roomNumber,
404	        RoomType roomType,
405	        LocalDate checkIn,
406	        LocalDate checkOut,
407	        int nights,
408	        BigDecimal subtotal,
409	        BigDecimal discount,
410	        BigDecimal total) {
411	
412	    public ReservationReceipt(Reservation reservation, Room room) {
413	        this(
414	                "Comprovante de reserva",
415	                reservation.id(),
416	                reservation.guest().name(),
417	                reservation.guest().cpf(),
418	                room.number(),
419	                room.type(),
420	                reservation.checkIn(),
421	                reservation.checkOut(),
422	                reservation.price().nights(),
423	                reservation.price().subtotal(),
424	                reservation.price().discount(),
425	                reservation.price().total());
426	    }
427	
428	    public String text() {
429	        StringBuilder text = new StringBuilder();
430	        text.append(title).append(" nº ").append(reservationId).append('\n');
431	        text.append("Hóspede: ").append(guestName).append(" (CPF ").append(guestCpf).append(")\n");
432	        text.append("Quarto: ").append(roomNumber).append(" (").append(roomType).append(")\n");
433	        text.append("Entrada: ").append(TextFormat.date(checkIn))
434	                .append(" | Saída: ").append(TextFormat.date(checkOut))
435	                .append(" | ").append(nights).append(nights == 1 ? " diária" : " diárias").append('\n');
436	        text.append("Diárias: ").append(TextFormat.money(subtotal)).append('\n');
437	        if (discount.signum() > 0) {
438	            text.append("Desconto: ").append(TextFormat.money(discount)).append('\n');
439	        }
440	        text.append("Total: ").append(TextFormat.money(total)).append('\n');
441	        return text.toString();
442	    }
443	}

